import axios from 'axios';
import React, { useState, useEffect, useCallback } from 'react';
import { FixedSizeList } from 'react-window';
import InfiniteLoader from 'react-window-infinite-loader';

function ToDoList() {

    const [tasks, setTasks] = useState([]);
    const [newTask, setNewTask] = useState("");
    const [searchTerm, setSearchTerm] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [hasMore, setHasMore] = useState(true);

    const pageSize = 50;

    useEffect(() => {
        loadMoreTasks(0);
    }, []);

    const loadMoreTasks = async (startIndex) => {
        if (isLoading || !hasMore) return;

        setIsLoading(true);
        try {
            const response = await axios.get(`http://localhost:5001/tasks?start=${startIndex}&limit=${pageSize}`);
            if (response.data.length === 0) {
                setHasMore(false);
            } else {
                setTasks((prevTasks) => [...prevTasks, ...response.data]);
            }
        } catch (error) {
            console.error('Error loading more tasks:', error);
        }
        setIsLoading(false);
    };

    function handleSearchChange(event) {
        setSearchTerm(event.target.value);
    }

    const filteredTasks = tasks.filter(task =>
        task.text.toLowerCase().includes(searchTerm.toLowerCase())
    );

    function handleInputChange(event) {
        setNewTask(event.target.value);
    }

    async function addTask() {
        if (newTask.trim() !== "") {
            try {
                const response = await axios.post('http://localhost:5001/tasks', { text: newTask });
                setTasks((prevTasks) => [response.data, ...prevTasks]);
                setNewTask("");
            } catch (error) {
                console.error('Error adding task:', error);
            }
        }
    }

    async function deleteTask(id) {
        try {
            await axios.delete(`http://localhost:5001/tasks/${id}`);
            setTasks((prevTasks) => prevTasks.filter(task => task._id !== id));
        } catch (error) {
            console.error('Error deleting task:', error);
        }
    }

    async function moveTaskUp(index) {
        if (index > 0) {
            try {
                const response = await axios.put('http://localhost:5001/tasks/reorder', {
                    sourceIndex: index,
                    destinationIndex: index - 1
                });
                setTasks(response.data);
            } catch (error) {
                console.error('Error moving task up:', error);
            }
        }
    }

    async function moveTaskDown(index) {
        if (index < tasks.length - 1) {
            try {
                const response = await axios.put('http://localhost:5001/tasks/reorder', {
                    sourceIndex: index,
                    destinationIndex: index + 1
                });
                setTasks(response.data);
            } catch (error) {
                console.error('Error moving task down:', error);
            }
        }
    }

    function callConsoleLog() {
        console.log(tasks);
    }

    async function generateTasks() {
        const newTasks = Array.from({ length: 20000 }, (_, i) => `Task ${i + 1}`);
        for (const task of newTasks) {
            await axios.post('http://localhost:5001/tasks', { text: task });
        }
        const response = await axios.get('http://localhost:5001/tasks');
        setTasks(response.data);
    }

    const isItemLoaded = (index) => index < tasks.length;

    const loadMoreItems = useCallback(async (startIndex, stopIndex) => {
        if (!isLoading) {
            await loadMoreTasks(startIndex);
        }
    }, [isLoading]);

    return (
        <div className="to-do-list">
            <h1>To-Do List</h1>

            {/* ✅ Search and Input Section */}
            <div className="input-section">
                <input
                    type="text"
                    placeholder="Search tasks..."
                    value={searchTerm}
                    onChange={handleSearchChange}
                    className="search-bar"
                />
                <input
                    type="text"
                    placeholder="Enter a Task.."
                    value={newTask}
                    onChange={handleInputChange}
                    className="task-input"
                />
                <button className="add-button" onClick={addTask}>
                    Add
                </button>
                <button className="log-button" onClick={callConsoleLog}>
                    LOG
                </button>
                <button className="generate-button" onClick={generateTasks}>
                    Generate 2,000 Tasks
                </button>
            </div>

            {/* ✅ Infinite Scrolling */}
            <InfiniteLoader
                isItemLoaded={isItemLoaded}
                itemCount={hasMore ? tasks.length + 1 : tasks.length}
                loadMoreItems={loadMoreItems}
            >
                {({ onItemsRendered, ref }) => (
                    <FixedSizeList
                        height={400}
                        width="100%"
                        itemSize={50}
                        itemCount={filteredTasks.length}
                        onItemsRendered={onItemsRendered}
                        ref={ref}
                    >
                        {({ index, style }) => {
                            if (!isItemLoaded(index)) {
                                return (
                                    <div style={style} className="loading">
                                        Loading...
                                    </div>
                                );
                            }

                            const task = filteredTasks[index];

                            return (
                                <li style={style} key={task._id} className="task-item">
                                    <span className="task-text">{task.text}</span>
                                    <button className="delete-button" onClick={() => deleteTask(task._id)}>
                                        Delete
                                    </button>
                                    <button className="move-button" onClick={() => moveTaskUp(index)}>
                                        🔼
                                    </button>
                                    <button className="move-button" onClick={() => moveTaskDown(index)}>
                                        🔽
                                    </button>
                                </li>
                            );
                        }}
                    </FixedSizeList>
                )}
            </InfiniteLoader>

            {isLoading && <p className="loading-text">Loading more tasks...</p>}
        </div>
    );
}

export default ToDoList;
